private static final Pattern MULTIDOT = Pattern.compile("\\.+");

private String normalizeDots(String host) {
    if (host == null || host.isEmpty() || host.indexOf('.') == -1) {
        return host;
    }

    int start = 0;
    int end = host.length();
    boolean changed = false;

    // Remove leading dots
    while (start < end && host.charAt(start) == '.') {
        start++;
        changed = true;
    }

    // Remove trailing dots
    while (end > start && host.charAt(end - 1) == '.') {
        end--;
        changed = true;
    }

    if (changed) {
        host = host.substring(start, end);
    }

    // Replace multiple dots with a single dot
    host = MULTIDOT.matcher(host).replaceAll(".");

    return host;
}
